// แปลงข้อมูลดิบจาก Agent ให้เป็นรูปแบบมาตรฐาน และคำนวณว่ารอบนี้ผ่านหรือไม่
const raw = $input.first().json;
const b = raw.body ?? raw;

const dns_ok     = b.dns_ok === true || b.dns_ok === 'true';
const tcp_ok     = b.tcp_ok === true || b.tcp_ok === 'true';
const http_ok    = b.http_ok === true || b.http_ok === 'true';
const keyword_ok = b.keyword_ok === true || b.keyword_ok === 'true';

return [{
  json: {
    ts: new Date().toISOString(),
    domain: b.domain,
    checkpoint: b.checkpoint,
    isp: b.isp ?? null,
    region: b.region ?? 'TH',
    dns_ok,
    tcp_ok,
    http_ok,
    keyword_ok,
    status_code: Number(b.status_code ?? 0),
    latency_ms: b.latency_ms == null ? null : Number(b.latency_ms),
    ssl_days_left: b.ssl_days_left == null ? null : Number(b.ssl_days_left),
    ok: dns_ok && tcp_ok && http_ok && keyword_ok
  }
}];

// กฎกันแจ้งเตือนหลอน: ต้อง Fail 2 ครั้งติดกัน จากอย่างน้อย 2 จุดตรวจ
const rows = $input.all().map(i => i.json).filter(r => r && r.domain);
const current = $('แปลงข้อมูลที่ Agent ส่งมา').first().json;
const domain = current.domain;

const byCheckpoint = {};
for (const r of rows) {
  if (r.domain !== domain) continue;
  (byCheckpoint[r.checkpoint] = byCheckpoint[r.checkpoint] || []).push(r);
}

const failing = [];
for (const [cp, list] of Object.entries(byCheckpoint)) {
  const last2 = list
    .sort((a, b) => new Date(b.ts) - new Date(a.ts))
    .slice(0, 2);
  if (last2.length === 2 && last2.every(r => r.ok === false)) {
    failing.push({ checkpoint: cp, region: last2[0].region, isp: last2[0].isp });
  }
}

const thFail      = failing.filter(c => c.region === 'TH').length;
const foreignFail = failing.filter(c => c.region !== 'TH').length;
const hasForeign  = rows.some(r => r.region !== 'TH');
const sslMin      = Math.min(...rows.map(r => r.ssl_days_left).filter(v => v != null).concat([9999]));

return [{
  json: {
    domain,
    confirmed: failing.length >= 2,
    failing,
    th_fail: thFail,
    foreign_fail: foreignFail,
    has_foreign_probe: hasForeign,
    ssl_days_left: sslMin === 9999 ? null : sslMin,
    checked_at: new Date().toISOString()
  }
}];

// แยกประเภทเหตุโดยเทียบผลจากจุดตรวจในไทยกับจุดตรวจต่างประเทศ
const d = $json;
let type, severity, action;

if (d.th_fail >= 2 && d.foreign_fail === 0 && d.has_foreign_probe) {
  type     = 'ถูกบล็อกระดับ ISP';
  action   = 'สลับลิงก์กลางไปโดเมนสำรองถัดไปใน Domain Pool';
  severity = d.th_fail >= 3 ? 'P1' : 'P2';
} else if (d.th_fail >= 2 && d.foreign_fail >= 1) {
  type     = 'เซิร์ฟเวอร์หรือผู้ให้บริการโฮสต์ล่ม';
  action   = 'กู้เครื่องหรือ failover ไปเครื่องสำรอง และแจ้งผู้ให้บริการโฮสต์';
  severity = 'P1';
} else {
  type     = 'ผิดปกติบางจุดตรวจ ยังสรุปสาเหตุไม่ได้';
  action   = 'ตรวจสอบด้วยมือก่อน ยังไม่ต้องเปลี่ยนโดเมน';
  severity = 'P2';
}

const icon = severity === 'P1' ? '🔴' : '🟠';
const timeTH = new Date().toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' });

const message = [
  icon + ' ' + severity + ' · ' + d.domain,
  'ประเภทเหตุ: ' + type,
  'จุดตรวจที่ล้มเหลว: ' + d.failing.map(f => f.checkpoint + (f.isp ? ' (' + f.isp + ')' : '')).join(', '),
  'ในไทยล้มเหลว ' + d.th_fail + ' จุด · ต่างประเทศล้มเหลว ' + d.foreign_fail + ' จุด',
  'สิ่งที่ต้องทำ: ' + action,
  'เวลา: ' + timeTH,
  '',
  'กรุณากด Acknowledge ภายใน 5 นาที มิฉะนั้นระบบจะ Escalate อัตโนมัติ'
].join('\n');

const code = 'INC-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.floor(Date.now()/1000 % 100000);

return [{ json: Object.assign({}, d, { code, type, severity, action, message }) }];
